/**
 * lib/debt-ledger (#3708): the session-start surfacer must be O(1) per
 * session. These tests pin the cache hit (no scan), the HEAD-keyed miss
 * (exactly one scan, ledger written), the single-flight lock (a second
 * session serves the stale ledger and never scans), the non-git fallback,
 * and the O(1) per-file producer used by the write hook.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync, readFileSync, existsSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const mockExecFileSync = vi.fn();
vi.mock('node:child_process', () => ({
  execFileSync: (...args: unknown[]) => mockExecFileSync(...args),
}));

let cacheDir = '';
vi.mock('../../lib/paths.js', () => ({
  getCacheDir: () => cacheDir,
  getProjectDir: () => '/proj',
}));

import {
  loadOrBuildLedger,
  readLedger,
  writeLedger,
  parseScanOutput,
  updateLedgerForFile,
  LEDGER_VERSION,
  SCAN_CAP,
} from '../../lib/debt-ledger.js';
import { DEBT_TOKEN } from '../../lib/debt-markers.js';

const T = DEBT_TOKEN;
const HEAD_A = 'a'.repeat(40);
const HEAD_B = 'b'.repeat(40);
const PROJ = '/proj';

function gitExitOne(): never {
  const err = new Error('no matches') as Error & { status: number };
  err.status = 1;
  throw err;
}

/** Route execFileSync calls: git rev-parse -> head, git grep -> grepOut. */
function wireGit(head: string | null, grepOut: string | (() => string)) {
  mockExecFileSync.mockImplementation((cmd: string, args: string[]) => {
    if (cmd === 'git' && args[0] === 'rev-parse') {
      if (head === null) throw new Error('not a git repo');
      return `${head}\n`;
    }
    if (cmd === 'git' && args[0] === 'grep') {
      return typeof grepOut === 'function' ? grepOut() : grepOut;
    }
    if (cmd === 'grep') {
      return typeof grepOut === 'function' ? grepOut() : grepOut;
    }
    throw new Error(`unexpected exec: ${cmd} ${args.join(' ')}`);
  });
}

function grepCalls(): number {
  return mockExecFileSync.mock.calls.filter(
    (c) => (c[0] === 'git' && (c[1] as string[])[0] === 'grep') || c[0] === 'grep',
  ).length;
}

describe('lib/debt-ledger', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    cacheDir = mkdtempSync(join(tmpdir(), 'debt-ledger-'));
  });
  afterEach(() => {
    rmSync(cacheDir, { recursive: true, force: true });
  });

  it('cache hit on matching HEAD: one rev-parse, zero scans', () => {
    writeLedger({
      version: LEDGER_VERSION, head: HEAD_A, generated_at: new Date().toISOString(),
      entries: [{ file: 'src/a.ts', line: 3, choice: 'x', upgrade: 'y', trigger: 'z' }],
    });
    wireGit(HEAD_A, () => { throw new Error('scan must not run on a cache hit'); });

    const { ledger, source } = loadOrBuildLedger(PROJ);

    expect(source).toBe('cache');
    expect(ledger?.entries).toHaveLength(1);
    expect(grepCalls()).toBe(0);
  });

  it('HEAD changed: exactly one scan, ledger rewritten under the new HEAD', () => {
    writeLedger({ version: LEDGER_VERSION, head: HEAD_A, generated_at: new Date().toISOString(), entries: [] });
    wireGit(HEAD_B, [
      `src/auth.ts:14:// ${T}: session cookies, upgrade to JWT, when a 2nd service is added`,
      `src/db.ts:8:# ${T}: SQLite, upgrade to Postgres, when writers > 1`,
    ].join('\n'));

    const { ledger, source } = loadOrBuildLedger(PROJ);

    expect(source).toBe('scan');
    expect(grepCalls()).toBe(1);
    expect(ledger?.head).toBe(HEAD_B);
    expect(ledger?.entries.map((e) => `${e.file}:${e.line}`)).toEqual(['src/auth.ts:14', 'src/db.ts:8']);
    expect(readLedger()?.head).toBe(HEAD_B);
    // No lock left behind.
    expect(existsSync(join(cacheDir, 'debt-ledger.json.lock'))).toBe(false);
  });

  it('git grep exit 1 (no matches) is an empty ledger, not an error', () => {
    wireGit(HEAD_A, gitExitOne);
    const { ledger, source } = loadOrBuildLedger(PROJ);
    expect(source).toBe('scan');
    expect(ledger?.entries).toEqual([]);
    expect(readLedger()?.head).toBe(HEAD_A);
  });

  it('lock held by a live process: serves the stale ledger and never scans', () => {
    writeLedger({
      version: LEDGER_VERSION, head: HEAD_A, generated_at: new Date().toISOString(),
      entries: [{ file: 'old.ts', line: 1, choice: 'c', upgrade: 'u', trigger: 't' }],
    });
    mkdirSync(cacheDir, { recursive: true });
    writeFileSync(join(cacheDir, 'debt-ledger.json.lock'), String(process.pid));
    wireGit(HEAD_B, () => { throw new Error('scan must not run while locked'); });

    const { ledger, source } = loadOrBuildLedger(PROJ);

    expect(source).toBe('stale');
    expect(ledger?.entries[0].file).toBe('old.ts');
    expect(grepCalls()).toBe(0);
    // The other holder's lock survives.
    expect(readFileSync(join(cacheDir, 'debt-ledger.json.lock'), 'utf8')).toBe(String(process.pid));
  });

  it('lock held and no ledger at all: silent (null), never scans', () => {
    writeFileSync(join(cacheDir, 'debt-ledger.json.lock'), String(process.pid));
    wireGit(HEAD_A, () => { throw new Error('scan must not run while locked'); });
    const { ledger, source } = loadOrBuildLedger(PROJ);
    expect(source).toBe('locked');
    expect(ledger).toBeNull();
    expect(grepCalls()).toBe(0);
  });

  it('scan failure with a cached ledger serves the cached one as stale', () => {
    writeLedger({ version: LEDGER_VERSION, head: HEAD_A, generated_at: new Date().toISOString(), entries: [] });
    wireGit(HEAD_B, () => { throw new Error('git grep exploded'); });
    const { ledger, source } = loadOrBuildLedger(PROJ);
    expect(source).toBe('stale');
    expect(ledger?.head).toBe(HEAD_A);
    expect(existsSync(join(cacheDir, 'debt-ledger.json.lock'))).toBe(false);
  });

  it('outside a git repo: plain grep fallback, keyed as no-git', () => {
    wireGit(null, `/proj/src/x.ts:2:// ${T}: a, upgrade to b, when c`);
    const { ledger, source } = loadOrBuildLedger(PROJ);
    expect(source).toBe('scan');
    expect(ledger?.head).toBe('no-git');
    expect(mockExecFileSync.mock.calls.some((c) => c[0] === 'grep')).toBe(true);
    // Absolute paths from grep -r are made project-relative.
    expect(ledger?.entries[0].file).toBe('src/x.ts');
  });

  it('parseScanOutput skips malformed lines and non-marker content, and caps hits', () => {
    const lines = [
      'garbage-no-colons',
      '/proj/src/x.ts:3:const ork = 1; // unrelated',
      ...Array.from({ length: SCAN_CAP + 10 }, (_, i) => `src/f${i}.ts:${i + 1}:// ${T}: s${i}, upgrade to u${i}, when w${i}`),
    ];
    const entries = parseScanOutput(lines.join('\n'), PROJ);
    expect(entries.every((e) => e.file.startsWith('src/f'))).toBe(true);
    expect(entries.length).toBeLessThanOrEqual(SCAN_CAP + 1);
  });

  it('updateLedgerForFile replaces one file\'s entries in place (O(1) producer)', () => {
    writeLedger({
      version: LEDGER_VERSION, head: HEAD_A, generated_at: new Date().toISOString(),
      entries: [
        { file: 'src/keep.ts', line: 1, choice: 'k', upgrade: 'k2', trigger: 'kt' },
        { file: 'src/edit.ts', line: 9, choice: 'old', upgrade: 'o2', trigger: 'ot' },
      ],
    });

    updateLedgerForFile(PROJ, '/proj/src/edit.ts', [
      'const a = 1;',
      `// ${T}: new choice, upgrade to new path, when new trigger`,
    ].join('\n'));

    const after = readLedger();
    expect(after?.entries.map((e) => `${e.file}:${e.line}:${e.choice}`)).toEqual([
      'src/keep.ts:1:k',
      'src/edit.ts:2:new choice',
    ]);
    // HEAD key is untouched: a mid-session edit does not pretend to be a rebuild.
    expect(after?.head).toBe(HEAD_A);
  });

  it('updateLedgerForFile drops a file that no longer carries markers', () => {
    writeLedger({
      version: LEDGER_VERSION, head: HEAD_A, generated_at: new Date().toISOString(),
      entries: [{ file: 'src/done.ts', line: 4, choice: 'c', upgrade: 'u', trigger: 't' }],
    });
    updateLedgerForFile(PROJ, 'src/done.ts', 'clean file\n');
    expect(readLedger()?.entries).toEqual([]);
  });

  it('updateLedgerForFile is a no-op when there is no ledger yet', () => {
    updateLedgerForFile(PROJ, 'src/x.ts', `// ${T}: a, upgrade to b, when c`);
    expect(existsSync(join(cacheDir, 'debt-ledger.json'))).toBe(false);
  });
});
